  var card = $('m-home-card');
  card.hidden = !watched.length;
  if (watched.length) {
    var inside = watched.filter(function (p) { return p.home; });
    var wifi = pres.wifi || {};
    if (!wifi.enabled) {
      $('m-home').textContent = 'not asking';
