      if (live.why === 'by hand') want.appendChild(el('span', 'heat-hand', 'by hand' + (live.hold_until ? ' until ' + new Date(live.hold_until * 1000).toLocaleTimeString([], {hour: '2-digit', minute: '2-digit'}) : '')));
