    now.appendChild(ctl);
    head.appendChild(now);
    card.appendChild(head);
    var why = el('div', 'muted small');
    var thName = live.thermometer ? ((st.devices || []).filter(function (d) { return d.id === live.thermometer; })[0] || {}).name : '';
