          : 'holding the ' + live.why + ' temperature'))))
        + (live.valves.length ? ' \u00b7 ' + live.valves.map(function (v) { return v.name + (isNum(v.setpoint) ? ' at ' + fmt(v.setpoint, 1) : '') + (v.online ? '' : ' (silent)'); }).join(', ')
