      var b = el('button', 'btn small needs-unlock' + ((room.mode || 'plan') === pr[0] && live.why !== 'by hand' ? ' on' : ''),
                 (pr[0] === 'manual' ? '\u270b' : (ICON[pr[0] === 'off' ? 'shut' : pr[0]] || '')) + ' ' + pr[1]); b.type = 'button';
      b.title = pr[0] === 'plan' ? 'Follow the plan'
