  var mk = function (host, id) {
    var sw = makeSwitch(false, null);
    sw.input.id = id;
    $(host).appendChild(sw);
    return sw.input;
  };
  WIFI_SW = {enabled: mk('wifi-enabled-sw', 'wifi-enabled'), verify: mk('wifi-verify-sw', 'wifi-verify'),
