  var a = document.createElement('a');
  a.href = 'index.php?api=wifi-sshkey-download&session=' + encodeURIComponent(LOCK.token);
  a.download = 'zigmon-ap-key';
  document.body.appendChild(a); a.click(); a.remove();
};

