    color = value <= crit ? 'var(--crit)' : (value <= warn ? 'var(--warn)' : 'var(--ok)');
  } else {
    q = value >= -55 ? 4 : value >= -65 ? 3 : value >= -75 ? 2 : value >= -85 ? 1 : 0;
    color = q >= 3 ? 'var(--ok)' : (q === 2 ? 'var(--warn)' : 'var(--crit)');
  }
