// A setting's label is short; the long word waits under the pointer. What is
// worth saying there: what it does, an example where one helps, the key it has
// in config.json, what that file says, and whether what is running came from
// the file or was changed here.
var SETHELP = null;
function settingsHelpBox() {
  if (!SETHELP) {
    SETHELP = el('div', 'sethelp');
    document.body.appendChild(SETHELP);
  }
  return SETHELP;
}
// The same panel, for anything anywhere that has more to say than a label can
// hold. A native tooltip waits a second, wraps where it likes, cannot hold a
// line break or an icon, and is invisible on a touchscreen; this one appears
// at once, is styled like the rest of the page, and takes as many words as
// the thing deserves.
// A setting's words are text and are escaped as text; a handful of them were
// written with a little markup in them, which then appeared as markup. The
// answer is not to stop escaping - that is how a value with a bracket in it
// becomes a page - but to escape everything and then let three harmless tags
// back in afterwards.
function richText(text) {
  var safe = esc(String(text === undefined || text === null ? '' : text));
  return safe
    .replace(/&lt;(\/?)(code|i|b)&gt;/g, '<$1$2>')
    .replace(/\n/g, '<br>');
}
function helpAt(over, html) {
  var box = settingsHelpBox();
  box.innerHTML = html;
  box.style.display = 'block';
  var at = over.getBoundingClientRect();
  var wide = box.getBoundingClientRect();
  var left = Math.min(Math.max(8, at.left), window.innerWidth - wide.width - 12);
  var top = at.bottom + 8;
  if (top + wide.height > window.innerHeight - 8) top = Math.max(8, at.top - wide.height - 8);
  box.style.left = left + 'px';
  box.style.top = top + 'px';
}
// Give a thing the nice panel instead of the browser's tooltip. The title is
// kept, so a screen reader and a touch-and-hold still find the same words.
function explain(over, words, keep) {
  if (!over || !words) return over;
  var html = richText(words);
  if (keep !== false) over.title = String(words);
  over.dataset.explains = '1';
  over.addEventListener('mouseenter', function () { helpAt(over, html); });
  over.addEventListener('mouseleave', hideSettingHelp);
  over.addEventListener('focus', function () { helpAt(over, html); });
  over.addEventListener('blur', hideSettingHelp);
  return over;
}
// Everything already drawn that carries more than a label's worth of title,
// given the panel without any of it being rewritten. Written once a second's
// worth of drawing is done, and only once per element.
// What a button or a dropdown does, where the word on it is not the whole
// story. Written out by name rather than guessed: the ones that only save what
// is on screen say nothing here, and the ones that talk to a machine, throw
// something away or cost money say what that means before it is pressed.
var EXPLAIN_BY_ID = {
