// Whole families of controls that mean the same thing wherever they appear.
// Said by rule rather than one at a time: an "Add ..." button is an "Add ..."
// button in eleven cards, and eleven copies of one sentence go stale in
// eleven different ways.
function explainByFamily(host) {
  if (host !== document && host.matches && host.matches('button.btn,input,textarea')) {
    var one = host;
    var only = {querySelectorAll: function (sel) { return one.matches(sel) ? [one] : []; }};
    explainByFamily(only);
  }
  Array.prototype.forEach.call(host.querySelectorAll('button.btn'), function (b) {
    if (b.dataset.explains || b.title) return;
    var word = (b.textContent || '').trim();
    if (/^Add\b/.test(word)) {
      explain(b, word + '. A new empty line, here on the page only \u2014 nothing is written down or '
        + 'starts working until the card is saved.');
    } else if (/^Save\b/.test(word)) {
      explain(b, word + '. Writes what is on this card down and puts it to work at once, and asks for '
        + 'the PIN first. What other cards are holding unsaved is not touched.');
    } else if (/^Erase\b/.test(word)) {
      explain(b, word + '. What it erases cannot be got back except from a backup.');
    }
  });
  Array.prototype.forEach.call(host.querySelectorAll('input,textarea'), function (one) {
    if (one.dataset.explains || one.title) return;
    if (one.type === 'file') {
      explain(one, 'Choose a file from this computer. Nothing happens until it is chosen, and what it '
        + 'does then is described by the button that opened it.');
    } else if (one.placeholder) {
      explain(one, one.placeholder.length > 40 ? one.placeholder
        : ('For example: ' + one.placeholder));
    }
  });
}
function explainNamedThings(where) {
  var host = where || document;
  Object.keys(EXPLAIN_BY_ID).forEach(function (id) {
    var one = host.getElementById ? host.getElementById(id) : null;
    if (one && !one.dataset.explains) explain(one, EXPLAIN_BY_ID[id]);
  });
  Object.keys(EXPLAIN_SELECTS).forEach(function (id) {
    Array.prototype.forEach.call(host.querySelectorAll('select#' + id + ', select[data-id="' + id + '"]'),
      function (one) { if (!one.dataset.explains) explain(one, EXPLAIN_SELECTS[id]); });
  });
}
function explainLongTitles(where) {
  var host = where || document;
  if (host !== document) {
    // the node itself may be the thing with the title
    if (host.title && String(host.title).length >= 55 && !host.dataset.explains) {
      explain(host, host.title);
    }
  } else {
    explainNamedThings(document);
  }
  explainByFamily(host);
  Array.prototype.forEach.call(host.querySelectorAll('[title]'), function (one) {
    if (one.dataset.explains || String(one.title).length < 55) return;
    if (one.closest && one.closest('.sethelp')) return;
    explain(one, one.title);
  });
}
function showSettingHelp(over, key, info, words) {
