  var same = !info.overridden;
  helpAt(over, '<div>' + richText(words || '') + '</div>'
    + '<span class="k"><b>' + esc(key) + '</b> in config.json: '
    + (file === null ? '<i>not set</i>' : esc(String(file)))
    + (info.kind === 'secret' ? '' : (' \u00b7 now: ' + esc(String(now))))
    + '<br><span class="' + (same ? 'same' : 'diff') + '">'
    + (same ? 'the same as the file' : 'changed here, so the file is not what is running')
    + '</span></span>');
