    var row = el('div', 'compose-row');
    row.appendChild(el('label', '', label));
    var input = el('input');
    input.type = kind || 'text';
    input.value = parts[name] || '';
    if (hint) input.placeholder = hint;
    input.oninput = function () { parts[name] = input.value.trim(); settle(); };
    row.appendChild(input);
    return row;
  };
