function applySettingsWhen() {
  var grid = $('settings-grid'); if (!grid) return;
  var now = function (key) {
    var box = grid.querySelector('[data-k="' + key + '"]');
    if (!box) return '';
    // A switch is a checkbox, and a checkbox's value is the word "on"
    // whether it is on or not - so every rule that asked whether a switch was
    // off read NaN and answered yes. What is wanted is whether it is ticked.
    if (box.dataset.bool || box.type === 'checkbox') return box.checked ? '1' : '0';
    return String(box.value);
  };
  Array.prototype.forEach.call(grid.querySelectorAll('[data-when]'), function (item) {
    var parts = String(item.dataset.when).split('=');
