  // ignored and looks exactly like one that is not is how somebody sets a
  // thing three times and wonders why nothing changed.
  Object.keys(SETTINGS_IDLE).forEach(function (key) {
    var box = grid.querySelector('[data-k="' + key + '"]');
    var item = box && box.closest ? box.closest('.set-item') : null;
    if (!item) return;
    var why = '';
    SETTINGS_IDLE[key].some(function (rule) {
      if (rule[0](now)) { why = rule[1]; return true; }
      return false;
    });
    item.classList.toggle('idle', !!why);
    var note = item.querySelector('.idle-note');
    if (why) {
      if (!note) { note = el('span', 'idle-note', ''); item.appendChild(note); }
      note.textContent = why;
    } else if (note) {
      note.remove();
    }
  });
}
