  add(['ntfy_watch', 'ntfy_log', 'ntfy_error_log', 'ntfy_own_watch', 'ntfy_own_log', 'ntfy_ban_log'],
      [EMPTY('proxy_host'), 'not used while there is no server in front']);
  add(['ntfy_own_log', 'ntfy_ban_log'],
