}

// ---- messages waiting to go --------------------------------------------------
function renderOutbox(st) {
  var card = $('outbox-card'), host = $('outbox-list'); if (!card) return;
  var rows = st.sms_outbox || [];
  card.hidden = !rows.length;
  if (!rows.length) return;
