  if (allPlugs.filter(function (p) { return (p.role || 'plug') !== 'light'; }).length > 1)
    out.push(['*', withIcon('all', 'all sockets')]);
  if (allPlugs.filter(function (p) { return (p.role || 'plug') === 'light'; }).length > 1)
    out.push(['*lights', withIcon('light', 'all lights')]);
