  if (SCENES.rows === null) {
    api('scenes').then(function (r) {
      if (SCENES.dirty) return;                    // became dirty while this request was in flight
      SCENES.rows = (r.scenes || []).map(function (x) { return JSON.parse(JSON.stringify(x)); });
      paintScenes(st);
    }, function () {});
    return;
  }
  paintScenes(st);
}
