    .forEach(function (pair) {
      var label = el('div', 'notify-opt');
      var row = switchRow(pair[1], chosen[pair[0]] !== false && (pair[0] !== 'sms' || chosen.sms === true),
                          function () { NOTIFY.dirty = true; });
