function routerSheet() {
  withPin('Read the router now',
    'It logs in and reads the address list, both families. Nothing is changed.', function (pin) {
      return post('blocked-router', {pin: pin}).then(function (r) {
        if (!r.ok) throw new Error(r.error || 'could not read the router');
