    });
}
function drawRouterSheet(r) {
  showDetail('What the router is carrying', [], null, true);
  var host = $('attnbody');
  var lead = el('p', 'lead');
  lead.innerHTML = 'Read from the list <code>' + esc(r.list) + '</code> just now, in '
    + r.read_in_ms + ' ms \u2014 both the IPv4 and the IPv6 side. '
    + '<b>' + (r.carrying || []).length + '</b> address(es) on the router'
    + ((r.not_carried || []).length
       ? ', and <b>' + r.not_carried.length + '</b> kept out here that it is not carrying.' : '.');
  host.appendChild(lead);
  var sheet = el('div', 'alertsheet rtr');
  var draw = function (one, missing) {
    var card = el('div', 'ak' + (missing ? ' miss' : '') + (one.spared ? ' off' : ''));
    var head = el('h4');
    head.appendChild(el('span', 'addr', one.address));
    head.appendChild(el('span', 'road', one.family));
    if (one.from_proxy) head.appendChild(el('span', 'road', '\ud83c\udf10 seen at the server in front'));
    if (one.from_ntfy) head.appendChild(el('span', 'road', '\ud83d\udd14 seen at the notification server'));
    if (missing) head.appendChild(el('span', 'road none', 'not on the router'));
    else if (!one.ours) head.appendChild(el('span', 'road same', 'somebody else put it there'));
    else head.appendChild(el('span', 'road on', 'carried'));
    if (one.spared) head.appendChild(el('span', 'road none', 'let through anyway'));
    card.appendChild(head);
    if (one.why) card.appendChild(el('div', 'what', one.why));
    var grid = el('div', 'grid');
    var cell = function (title, value) {
      if (value === undefined || value === null || value === '') return;
      var box = el('div', 'cell');
      box.appendChild(el('b', '', title));
      box.appendChild(document.createTextNode(String(value)));
      grid.appendChild(box);
    };
    cell('kept out since', one.since ? stamp(one.since) : (one.known ? '' : 'not by this house'));
    // said as somebody would say it, not as 1440 minutes
    var howLong = function (seconds) {
      var mins = Math.ceil((seconds || 0) / 60);
      if (mins < 90) return mins + ' min';
      if (mins < 48 * 60) return Math.round(mins / 60) + ' h';
      return Math.round(mins / 1440) + ' days';
    };
    cell('how long left', one.forever ? 'for good' : (one.left ? howLong(one.left) : ''));
    cell('why that long', one.how);
    cell('turned away', one.hits ? one.hits + '\u00d7' : '');
    cell('put there by', one.by || (one.auto === false ? 'by hand' : (one.known ? 'the counting' : '')));
    cell('kept out before', one.before ? one.before + '\u00d7' : '');
    cell('on its account now', (one.score !== undefined && one.score !== null)
         ? (one.score + ' of ' + one.bar) : '');
    cell('the router says', one.comment || '');
    card.appendChild(grid);
    // The lines it was judged on, kept with the block at the moment it was
    // made. The counter behind them holds only the last few minutes, so an
    // hour later there would be nothing to show - or worse, whatever the
    // address had done since, which reads as the reason and is not.
    var proofOf = function (rows, words) {
      if (!(rows || []).length) return null;
      var proof = el('div', 'proof');
      proof.appendChild(el('div', 'ph', words.replace('%d', rows.length)));
      rows.slice().reverse().forEach(function (e) {
        var line = el('div', 'pl');
        line.appendChild(el('span', 't', stamp(e.when)));
        line.appendChild(document.createTextNode((e.detail || e.words || '') + '   \u2014 ' + e.words));
        proof.appendChild(line);
