        card.appendChild(head);
        card.appendChild(el('div', 'what', 'Sent when a rule, a schedule, a one-tap link or a text asks '
          + 'for it by name. The same one is not repeated within '
          + (m.quiet_s === 0 ? 'no time at all' : Math.round((m.quiet_s || 900) / 60) + ' min') + '.'));
        var roads = el('div', 'roads');
        if (off) {
          roads.appendChild(el('span', 'road none', 'said nowhere'));
        } else {
